import PropTypes from 'prop-types';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';
import Spinner from '../Comonent/Spinner';

const AuthContext = createContext(undefined);
const ACCESS_TOKEN_KEY = 'accessToken';

const getStoredToken = () => {
  if (typeof window === 'undefined') {
    return null;
  }
  return window.localStorage.getItem(ACCESS_TOKEN_KEY);
};

export const AuthProvider = ({ children }) => {
  const [accessToken, setAccessTokenState] = useState(getStoredToken);
  const [user, setUser] = useState(null);
  const [initializing, setInitializing] = useState(true);

  const persistToken = useCallback((token) => {
    if (typeof window === 'undefined') {
      setAccessTokenState(token ?? null);
      return;
    }
    if (token) {
      window.localStorage.setItem(ACCESS_TOKEN_KEY, token);
      setAccessTokenState(token);
    } else {
      window.localStorage.removeItem(ACCESS_TOKEN_KEY);
      setAccessTokenState(null);
    }
  }, []);

  const refreshAccessToken = useCallback(async () => {
    try {
      const response = await fetch('/api/auth/refresh', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
      });
      if (!response.ok) {
        return null;
      }
      const body = await response.json();
      const token = body?.data?.accessToken;
      if (token) {
        persistToken(token);
        return token;
      }
    } catch (error) {
      console.error('Failed to refresh access token', error);
    }
    return null;
  }, [persistToken]);

  const authFetch = useCallback(
    async (input, init = {}) => {
      const headers = new Headers(init.headers || {});
      if (accessToken) {
        headers.set('Authorization', `Bearer ${accessToken}`);
      }
      let response = await fetch(input, {
        ...init,
        headers,
        credentials: 'include',
      });

      if (response.status !== 401) {
        return response;
      }

      const refreshedToken = await refreshAccessToken();
      if (!refreshedToken) {
        persistToken(null);
        setUser(null);
        return response;
      }

      const retryHeaders = new Headers(init.headers || {});
      retryHeaders.set('Authorization', `Bearer ${refreshedToken}`);

      response = await fetch(input, {
        ...init,
        headers: retryHeaders,
        credentials: 'include',
      });
      return response;
    },
    [accessToken, persistToken, refreshAccessToken],
  );

  const login = useCallback(
    async (email, password) => {
      try {
        const response = await fetch('/api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ email, password }),
        });

        if (!response.ok) {
          let message = 'Unable to log in with provided credentials.';
          try {
            const errorBody = await response.json();
            message = errorBody?.error?.message ?? message;
          } catch (parseError) {
            console.error('Failed to parse login error response', parseError);
          }
          throw new Error(message);
        }

        const body = await response.json();
        const token = body?.data?.accessToken ?? null;
        const userData = body?.data?.user ?? null;

        if (token) {
          persistToken(token);
        }
        setUser(userData);
        return userData;
      } catch (error) {
        console.error('Login request failed', error);
        throw error;
      }
    },
    [persistToken],
  );

  const logout = useCallback(async () => {
    try {
      const headers = new Headers();
      if (accessToken) {
        headers.set('Authorization', `Bearer ${accessToken}`);
      }
      await fetch('/api/auth/logout', {
        method: 'POST',
        credentials: 'include',
        headers,
      });
    } catch (error) {
      console.error('Logout request failed', error);
    } finally {
      persistToken(null);
      setUser(null);
    }
  }, [accessToken, persistToken]);

  const loadCurrentUser = useCallback(async () => {
    if (!accessToken) {
      setInitializing(false);
      return;
    }

    try {
      const response = await authFetch('/api/auth/me');
      if (!response.ok) {
        if (response.status === 401) {
          persistToken(null);
          setUser(null);
        }
        setInitializing(false);
        return;
      }
      const body = await response.json();
      setUser(body?.data ?? null);
    } catch (error) {
      console.error('Failed to load current user', error);
    } finally {
      setInitializing(false);
    }
  }, [accessToken, authFetch, persistToken]);

  useEffect(() => {
    loadCurrentUser();
  }, [loadCurrentUser]);

  const contextValue = useMemo(
    () => ({
      user,
      isAuthenticated: Boolean(user),
      initializing,
      login,
      logout,
      authFetch,
      refreshAccessToken,
      persistToken,
      accessToken,
    }),
    [user, initializing, login, logout, authFetch, refreshAccessToken, persistToken, accessToken],
  );

  if (initializing) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-white">
        <Spinner loading />
      </div>
    );
  }

  return <AuthContext.Provider value={contextValue}>{children}</AuthContext.Provider>;
};

AuthProvider.propTypes = {
  children: PropTypes.node.isRequired,
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
